 for(const el of map.elements){if(!el.tags.highway||el.tags.highway==='construction'||el.tags.tunnel==='yes')continue;let parts=[],part=[];for(let i=1;i<el.geometry.length;i++){const pair=clip(el.geometry[i-1],el.geometry[i]);if(!pair){if(part.length>1)parts.push(part);part=[];continue}if(!part.length)part.push(pair[0]);else if(Math.hypot(part.at(-1).x-pair[0].x,part.at(-1).z-pair[0].z)>.02){parts.push(part);part=[pair[0]]}part.push(pair[1])}if(part.length>1)parts.push(part);for(let j=0;j<parts.length;j++){const p=parts[j].map(v=>{const q=new T.Vector2(v.x,v.z);q.node=v.node;return q}),width=parseFloat(el.tags.width)||(['primary','secondary','tertiary'].includes(el.tags.highway)?11:['footway','path','cycleway','steps','track'].includes(el.tags.highway)?2:el.tags.highway==='service'?4:7),r={id:el.id+'-'+j,tags:el.tags,p,name:el.tags.name||'',type:el.tags.highway,width:clamp(width,1.2,20),bridge:!!el.tags.bridge&&el.tags.bridge!=='no'};r.cumulative=[0];for(let k=1;k<p.length;k++)r.cumulative.push(r.cumulative.at(-1)+p[k].distanceTo(p[k-1]));r.length=r.cumulative.at(-1);if(r.length>.2)roads.push(r)}}
