 function height(r,i,t,x,z){if(r.bridge)return T.MathUtils.lerp(r.deckStart,r.deckEnd,(r.cumulative[i]+r.p[i].distanceTo(r.p[i+1])*t)/r.length);const a=r.p[i],b=r.p[i+1],len=a.distanceTo(b),ya=overrides.get(nodeKey(a)),yb=overrides.get(nodeKey(b));let h=hydro.ground(x,z)+.16;if(ya!==undefined)h+=(ya-(hydro.ground(a.x,a.y)+.16))*Math.max(0,1-len*t/25);if(yb!==undefined)h+=(yb-(hydro.ground(b.x,b.y)+.16))*Math.max(0,1-len*(1-t)/25);return h}
 const spatial=new Map();for(const r of roads)for(let i=0;i<r.p.length-1;i++){const a=r.p[i],b=r.p[i+1];for(let x=Math.floor((Math.min(a.x,b.x)-r.width)/50);x<=Math.floor((Math.max(a.x,b.x)+r.width)/50);x++)for(let z=Math.floor((Math.min(a.y,b.y)-r.width)/50);z<=Math.floor((Math.max(a.y,b.y)+r.width)/50);z++){const key=x+','+z;if(!spatial.has(key))spatial.set(key,[]);spatial.get(key).push({r,i})}}
 function at(x,z,onlyBridge=false){let best=null;for(const seg of spatial.get(Math.floor(x/50)+','+Math.floor(z/50))||[]){const{r,i}=seg;if(onlyBridge&&!r.bridge)continue;const a=r.p[i],b=r.p[i+1],dx=b.x-a.x,dz=b.y-a.y,t=clamp(((x-a.x)*dx+(z-a.y)*dz)/(dx*dx+dz*dz||1),0,1),d=Math.hypot(x-a.x-dx*t,z-a.y-dz*t);if(!best||d<best.d)best={r,i,t,d}}return best}
 const arrays={road:[],pavement:[],line:[],structure:[],rail:[]};
 function strip(r,i,t0,t1,width,offset,key){const a=r.p[i],b=r.p[i+1],dx=b.x-a.x,dz=b.y-a.y,len=Math.hypot(dx,dz);if(!len)return;const nx=dz/len,nz=-dx/len,steps=Math.max(1,Math.ceil(len*(t1-t0)/(Math.hypot(a.x,a.y)<1300?2.5:6))),cross=Math.max(1,Math.ceil(width/2.5));for(let k=0;k<steps;k++)for(let j=0;j<cross;j++){const verts=[];for(const[t,side]of [[t0+(t1-t0)*k/steps,-width/2+j*width/cross],[t0+(t1-t0)*k/steps,-width/2+(j+1)*width/cross],[t0+(t1-t0)*(k+1)/steps,-width/2+(j+1)*width/cross],[t0+(t1-t0)*(k+1)/steps,-width/2+j*width/cross]]){const x=a.x+dx*t+nx*side,z=a.y+dz*t+nz*side;verts.push([x,height(r,i,t,x,z)+offset,z])}for(const n of [0,2,1,0,3,2])arrays[key].push(...verts[n])}}
 function beam(a,b,width,depth,key){const center=new T.Vector3().addVectors(a,b).multiplyScalar(.5),direction=new T.Vector3().subVectors(b,a),g=new T.BoxGeometry(width,depth,direction.length()),m=new T.Matrix4().lookAt(a,b,new T.Vector3(0,1,0));m.setPosition(center);g.applyMatrix4(m);const non=g.toNonIndexed();arrays[key].push(...non.attributes.position.array);g.dispose();non.dispose()}
