 for(const key of Object.keys(arrays)){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(arrays[key],3));const uv=new Float32Array(arrays[key].length/3*2);for(let i=0,j=0;i<arrays[key].length;i+=3,j+=2){uv[j]=arrays[key][i]/5;uv[j+1]=arrays[key][i+2]/5}g.setAttribute('uv',new T.BufferAttribute(uv,2));g.computeVertexNormals();scene.add(new T.Mesh(g,new T.MeshLambertMaterial({color:key==='line'?'#f5f2db':key==='rail'?'#aabac1':key==='structure'?'#8d989c':'#ffffff',map:key==='road'?textures.asphalt:key==='pavement'?textures.concrete:null,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:key==='line'?-4:-2,polygonOffsetUnits:-2})))}
